files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0ff;
  --accent: #6c63ff;
  --green: #4caf50;
  --yellow: #ffc107;
  --blue: #2196f3;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 20px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  font-size: 1.8rem;
  letter-spacing: 1px;
  color: var(--accent);
}

/* Pixel pet */
.pet {
  width: 120px;
  height: 120px;
  position: relative;
}

.pet-body {
  width: 100%;
  height: 100%;
  background: #ffb74d;
  border-radius: 16px;
  position: relative;
  box-shadow: 0 0 0 4px #e65100;
  image-rendering: pixelated;
}

.pet-eye {
  width: 16px;
  height: 16px;
  background: #1e1e2f;
  border-radius: 50%;
  position: absolute;
  top: 35%;
}

.pet-eye.left { left: 25%; }
.pet-eye.right { right: 25%; }

.pet-mouth {
  width: 40px;
  height: 8px;
  background: #1e1e2f;
  border-radius: 4px;
  position: absolute;
  bottom: 25%;
  left: 50%;
  transform: translateX(-50%);
}

/* Mood text */
.mood {
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--yellow);
  min-height: 1.5em;
}

/* Stats */
.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.9rem;
  font-weight: 500;
  color: #b0b0d0;
}

.bar-bg {
  width: 100%;
  height: 20px;
  background: #3a3a55;
  border-radius: 10px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 50%;
  border-radius: 10px;
  transition: width 0.3s ease;
}

.bar-fill.hunger { background: var(--green); }
.bar-fill.happiness { background: var(--yellow); }
.bar-fill.energy { background: var(--blue); }

/* Buttons */
.buttons {
  display: flex;
  gap: 12px;
  width: 100%;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  flex: 1;
  min-width: 80px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: white;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: #5a52e0;
}

button:focus-visible {
  outline: 3px solid var(--yellow);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.95);
}

/* Responsive */
@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  .buttons {
    flex-direction: column;
  }
  button {
    width: 100%;
  }
}

const state = {
  hunger: 50,
  happiness: 50,
  energy: 50
};

const moodEl = document.getElementById('mood');
const hungerFill = document.getElementById('hunger-fill');
const happinessFill = document.getElementById('happiness-fill');
const energyFill = document.getElementById('energy-fill');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerFill.style.width = state.hunger + '%';
  happinessFill.style.width = state.happiness + '%';
  energyFill.style.width = state.energy + '%';

  document.getElementById('hunger-bar').setAttribute('aria-valuenow', state.hunger);
  document.getElementById('happiness-bar').setAttribute('aria-valuenow', state.happiness);
  document.getElementById('energy-bar').setAttribute('aria-valuenow', state.energy);

  let mood = 'Happy';
  if (state.hunger < 30) mood = 'Hungry';
  else if (state.happiness < 30) mood = 'Sad';
  else if (state.energy < 30) mood = 'Tired';
  else if (state.hunger < 50 || state.happiness < 50 || state.energy < 50) mood = 'Okay';
  moodEl.textContent = 'Mood: ' + mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 5);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
